import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [tab, setTab] = useState("Нүүр");
  const [home, setHome] = useState("list");

  function Body() {
    if (tab === "Нүүр") {
      if (home === "detail") {
        return (
          <View style={styles.pad}>
            <Text nativeID="hd" style={styles.h}>Бараа: Утасгүй чихэвч</Text>
            <Pressable nativeID="hback" style={styles.btn} onPress={() => setHome("list")}>
              <Text style={styles.btnText}>← Буцах</Text>
            </Pressable>
          </View>
        );
      }
      return (
        <View style={styles.pad}>
          <Pressable nativeID="open" style={styles.btn}>
            <Text style={styles.btnText}>Утасгүй чихэвч</Text>
          </Pressable>
          {/* энд бичнэ үү: open дархад home-г "detail" болго */}
        </View>
      );
    }
    return <View style={styles.pad}><Text style={styles.h}>{tab}</Text></View>;
  }

  return (
    <View style={styles.container}>
      <View style={styles.bodyWrap}><Body /></View>
      <View nativeID="tabbar" style={styles.tabbar}>
        {["Нүүр", "Сагс", "Профайл"].map((t, i) => (
          <Pressable key={t} nativeID={"tab" + i} style={styles.tab} onPress={() => setTab(t)}>
            <Text style={styles.tabText}>{t}</Text>
          </Pressable>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  bodyWrap: { flex: 1 },
  pad: { flex: 1, padding: 24, gap: 14, justifyContent: "center" },
  h: { fontSize: 20, fontWeight: "bold" },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  tabText: { fontWeight: "600", color: "#334155" },
});

registerRootComponent(App);

